import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { validateSnapshotManifest, validateSnapshotPart, validateSnapshotObject, validateSnapshotInventory } from '../src/lib/inspiration/snapshot-protocol';
import type { InspirationSnapshotRecipient } from '@brandai/contracts';

type PythonVector = {
  synthetic_only: true;
  manifest: string;
  parts: Record<string, string>;
  objects: Record<string, string>;
  publicKey: string;
  keyId: string;
  recipient: InspirationSnapshotRecipient;
};

// Generated by Omni's actual snapshot_v3.publish_snapshot, not a TypeScript
// reimplementation of its signer. Only the synthetic public key is persisted.
const files = [new URL('./fixtures/inspiration-snapshot-python.json', import.meta.url)];
// Large synthetic interop vectors stay out of Git. This explicit test-only
// directory enables the same checks against 2001/10000-record publisher runs.
const extraDirectory = process.env.INSPIRATION_SNAPSHOT_TEST_VECTOR_DIR;
const extras = extraDirectory ? [2001, 10000].map(count => resolve(extraDirectory, `vector-${count}`, 'fixture.json')) : [];

describe.each([...files, ...extras])('actual Python publisher snapshot %s', file => {
  const vector = JSON.parse(readFileSync(file, 'utf8')) as PythonVector;
  const keys = {[vector.keyId]: vector.publicKey};
  const raw = Buffer.from(vector.manifest, 'base64');

  it('verifies real Python signatures, complete catalog and actual decoded object bytes', async () => {
    expect(vector.synthetic_only).toBe(true);
    expect(Object.keys(vector).some(name => /private/i.test(name))).toBe(false);
    const manifest = validateSnapshotManifest(raw, keys, vector.recipient);
    const parts = manifest.parts.map(descriptor => validateSnapshotPart(Buffer.from(vector.parts[descriptor.sha256]!, 'base64'), descriptor, manifest));
    expect(validateSnapshotInventory(manifest, parts).recordsCount).toBe(manifest.records_count);
    const checked = new Set<string>();
    for (const part of parts) for (const object of part.objects) {
      if (!checked.has(object.sha256)) {
        await validateSnapshotObject(Buffer.from(vector.objects[object.sha256]!, 'base64'), object);
        checked.add(object.sha256);
      }
    }
    expect(checked.size).toBe(manifest.image_count);
  }, 60_000);

  it('does not reinterpret the Python grant for a different library', () => {
    expect(() => validateSnapshotManifest(raw, keys, {...vector.recipient, library_id: 'other-library'})).toThrow('recipient');
  });
});
